CREATE TABLE IF NOT EXISTS hr_probation_periods (
 id TEXT PRIMARY KEY,tenant_id TEXT NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,company_id TEXT NOT NULL REFERENCES companies(id) ON DELETE RESTRICT,branch_id TEXT NOT NULL REFERENCES branches(id) ON DELETE RESTRICT,staff_id TEXT NOT NULL REFERENCES staff(id) ON DELETE CASCADE,started_at DATE NOT NULL,end_at DATE NOT NULL,status TEXT NOT NULL DEFAULT 'ACTIVE',final_decision TEXT,decision_note TEXT,decided_by TEXT,decided_at TIMESTAMP(3),created_by TEXT,created_at TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT hr_probation_dates_chk CHECK(end_at>=started_at),CONSTRAINT hr_probation_status_chk CHECK(status IN ('ACTIVE','COMPLETED','CANCELLED')),CONSTRAINT hr_probation_decision_chk CHECK(final_decision IS NULL OR final_decision IN ('CONFIRMED','EXTENDED','TERMINATED')));
CREATE UNIQUE INDEX IF NOT EXISTS hr_probation_active_staff_idx ON hr_probation_periods(tenant_id,staff_id) WHERE status='ACTIVE';CREATE INDEX IF NOT EXISTS hr_probation_staff_idx ON hr_probation_periods(tenant_id,staff_id,started_at DESC);
CREATE TABLE IF NOT EXISTS hr_probation_reviews (
 id TEXT PRIMARY KEY,tenant_id TEXT NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,probation_id TEXT NOT NULL REFERENCES hr_probation_periods(id) ON DELETE CASCADE,review_day INTEGER NOT NULL,scheduled_date DATE NOT NULL,status TEXT NOT NULL DEFAULT 'PENDING',reviewer_staff_id TEXT REFERENCES staff(id) ON DELETE SET NULL,rating DECIMAL(4,2),strengths TEXT,development_areas TEXT,manager_note TEXT,completed_by TEXT,completed_at TIMESTAMP(3),created_at TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT hr_probation_review_day_chk CHECK(review_day IN (30,60,90)),CONSTRAINT hr_probation_review_status_chk CHECK(status IN ('PENDING','COMPLETED','SKIPPED')),CONSTRAINT hr_probation_rating_chk CHECK(rating IS NULL OR (rating>=0 AND rating<=5)),UNIQUE(probation_id,review_day));CREATE INDEX IF NOT EXISTS hr_probation_reviews_due_idx ON hr_probation_reviews(tenant_id,scheduled_date,status);
